import SwiftUI

struct ContentView: View {

    @State var counter = 0
    @State var message = ""

    var body: some View {
        VStack {
            Text("\(counter)")

            Button {
                print("Raise Flag!!")
                counter += 1

                if counter >= 40 {
                    message = "See this island"
                } else if counter >= 30 {
                    message = "Every grain of sand"
                } else {
                    message = "Hear this anthem"
                }
            } label: {
                Text("Raise Flag")
                    .padding()
                    .background(.blue)
                    .foregroundColor(.white)
            }

            if counter >= 20 {
                Text(message)
            }
        }
    }
}

